def solve(data):
    ixps, rib, priors, declared, order, queries = validate(data)

    # Normalize and aggregate accepted RIB paths.
    aggregated = {}
    all_edges = set()
    for rawpath, count in rib:
        p = normalize_path(rawpath, ixps)
        if len(p) < 2 or len(set(p)) != len(p):
            continue
        aggregated[p] = aggregated.get(p, 0) + count
        prev = p[0]
        for cur in p[1:]:
            all_edges.add(canonical(prev, cur))
            prev = cur
    if len(all_edges) > 4096:
        raise Invalid()

    rounds, core_paths, core_edges = peel(aggregated)
    if len(core_edges) > 64:
        raise Invalid()
    core_links = sorted(core_edges)
    edge_index = {e: i for i, e in enumerate(core_links)}

    scopes, occurrences = build_scopes_and_occurrences(core_paths, edge_index)
    pos_of_var = validate_order_and_width(order, core_links, scopes)

    factors = make_factors(len(core_links), scopes, occurrences)
    m = len(core_links)
    if m == 0:
        Z = 1
    else:
        Z = run_ve(factors, m, pos_of_var)
    if Z == 0:
        return {"error": "zero-partition"}

    core_marginals = {}
    for i, e in enumerate(core_links):
        nums = []
        for t in range(3):
            nums.append(run_ve(factors, m, pos_of_var, (i, t)))
        core_marginals[e] = tuple(Fraction(n, Z) for n in nums)

    uniform = (Fraction(1, 3), Fraction(1, 3), Fraction(1, 3))
    links_out = []
    for e in sorted(all_edges):
        if e in edge_index:
            rnd = 0
            prob = core_marginals[e]
        else:
            rnd = rounds.get(e)
            if rnd is None:
                # Should be unreachable for a valid peeling computation.
                raise Invalid()
            prob = priors.get(e, uniform)
        links_out.append({
            "link": [e[0], e[1]],
            "round": rnd,
            "prob": [float(prob[0]), float(prob[1]), float(prob[2])],
        })

    queries_out = score_queries(queries, ixps, priors, declared, core_marginals)
    return {"version": 1, "links": links_out, "queries": queries_out}


def main():
    try:
        data = parse_request()
        answer = solve(data)
    except Invalid:
        answer = {"error": "invalid"}
    except Exception:
        # A malformed or out-of-domain request must not produce a traceback.
        answer = {"error": "invalid"}
    sys.stdout.write(json.dumps(answer, separators=(",", ":"), allow_nan=False))
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
